# Hand-written R5900 versions of the game_tests.c kernels (the kernels of
# ps2-llvm-benchmarks; bench variants asm and asm-vu0: no VU0), generated by
# asm/gen/app_files.py from asm/gen/game.py. n32 ABI. The kernels use the
# data of game_tests.c (KERNEL_DATA) and end with app_hash of their output.
# Optimized: yes, all. Measured on the PS2 (asm/harness/app.c, set game),
# feature clang (-mvu0) and gcc in parentheses:
#   Copy Loop       100.1 MB/s (96.9, 80.8)  lq/sq 64 bytes per iteration,
#                   PREF of the source 4 lines ahead (none: 96.4)
#   Packet Build    4.66 Mvert/s (4.32, 3.46) MMI, 4 vertices in the lanes
#                   (scalar, 4 sd per vertex: 4.18)
#   LZ Decompress   61.8 MB/s (38.7, 31.6)   copies of 8 bytes by ldl/ldr
#   Particles       4.94 Mpart/s (4.90, 4.75) memory-bound (~60 cycles per
#                   particle: one miss at a time); 16 particles per
#                   iteration, the six PREFs 2 lines ahead spread over it
#                   (all six every 4 particles: 4.66; none: 4.66)
#   Tri Raster      50.8 Mpix/s (38.1, 37.2) MMI, the edge functions of 4
#                   pixels in the lanes, a select with the frame

	.set	noreorder
	.set	noat

# gfx_mem: the offsets of its buffers
#define SPRITE		0x0000
#define FRAME		0x4400
#define INDEXED		0x8800
#define PALETTE		0x9c00
#define FRAME16		0xa000
#define SCALED		0xc400
# geom_mem
#define VERTS		0x0000
#define NORMALS		0x2400
#define SCALED_V	0x4800
#define FACE_NORMALS	0x6c00
#define SCREEN		0x9400
#define XFORMED		0xb800
#define COLORS		0xdc00
#define FACE_NORMALS_V	0xec00
#define VISIBLE		0x10c00

# reg = symbol + offset (any 32-bit offset), using $1
#define ADDR(reg, sym, off) \
	lui	$1, %hi(sym); addiu reg, $1, %lo(sym); \
	lui	$1, ((off) >> 16); ori $1, $1, ((off) & 0xffff); addu reg, reg, $1

	.text

# game_copy: copy_dst = copy_src (64 KB): lq/sq, 64 bytes per iteration,
# PREF of the source 4 lines ahead.
	.p2align 3
	.globl	game_copy
	.ent	game_copy
game_copy:
	lui	$1, %hi(copy_src)
	addiu	$8, $1, %lo(copy_src)
	lui	$1, %hi(copy_dst)
	addiu	$9, $1, %lo(copy_dst)
	lui	$1, 1
	addu	$10, $8, $1
	.p2align 3
1:
	pref	0, 256($8)
	lq	$2, 0($8)
	lq	$3, 16($8)
	lq	$4, 32($8)
	lq	$5, 48($8)
	sq	$2, 0($9)
	sq	$3, 16($9)
	sq	$4, 32($9)
	sq	$5, 48($9)
	addiu	$8, $8, 64
	bne	$8, $10, 1b
	addiu	$9, $9, 64
	lui	$1, %hi(copy_dst)
	addiu	$4, $1, %lo(copy_dst)
	j	app_hash
	lui	$5, 1
	.end	game_copy


