# game_lz: LZ77 decoder: copies of 8 bytes (ldl/ldr, sdl/sdr) that may
# write up to 7 bytes past the end, which the next copy overwrites; matches
# closer than 8 bytes byte by byte.
	.p2align 3
	.globl	game_lz
	.ent	game_lz
game_lz:
	addiu	$sp, $sp, -16
	sd	$31, 0($sp)
	sd	$16, 8($sp)
	lui	$1, %hi(lz_in)
	addiu	$8, $1, %lo(lz_in)
	lui	$1, %hi(lz_in_len)
	lw	$1, %lo(lz_in_len)($1)
	addu	$9, $8, $1
	lui	$1, %hi(lz_out)
	addiu	$10, $1, %lo(lz_out)
	move	$11, $10
	.p2align 3
1:
	lbu	$2, 0($8)
	addiu	$8, $8, 1
	andi	$3, $2, 0x80
	bnez	$3, 4f
	addiu	$3, $2, 1
2:
	ldl	$12, 7($8)
	ldr	$12, 0($8)
	addiu	$3, $3, -8
	addiu	$8, $8, 8
	sdl	$12, 7($10)
	sdr	$12, 0($10)
	bgtz	$3, 2b
	addiu	$10, $10, 8
	addu	$8, $8, $3
	addu	$10, $10, $3
3:
	sltu	$1, $8, $9
	bnez	$1, 1b
	nop
	b	9f
	nop
4:
	lbu	$12, 0($8)
	lbu	$13, 1($8)
	andi	$3, $2, 0x7f
	addiu	$8, $8, 2
	sll	$12, $12, 8
	addiu	$3, $3, 3
	or	$12, $12, $13
	addiu	$12, $12, 1
	sltiu	$1, $12, 8
	bnez	$1, 6f
	subu	$14, $10, $12
5:
	ldl	$12, 7($14)
	ldr	$12, 0($14)
	addiu	$3, $3, -8
	addiu	$14, $14, 8
	sdl	$12, 7($10)
	sdr	$12, 0($10)
	bgtz	$3, 5b
	addiu	$10, $10, 8
	b	3b
	addu	$10, $10, $3
6:
	lbu	$12, 0($14)
	addiu	$3, $3, -1
	addiu	$14, $14, 1
	sb	$12, 0($10)
	bgtz	$3, 6b
	addiu	$10, $10, 1
	b	3b
	nop
9:
	subu	$16, $10, $11
	move	$4, $11
	addiu	$5, $0, -4
	jal	app_hash
	and	$5, $16, $5
	xor	$2, $2, $16
	ld	$31, 0($sp)
	ld	$16, 8($sp)
	jr	$31
	addiu	$sp, $sp, 16
	.end	game_lz


